"""extract key-value pairs from a url query string

    for example
    "collection=23&someoption&format=json"
      -> {"collection": "23", "someoption": None, "format": "json"}

    """
def _parse_query(query: Any) -> object {
    parts = [p.split("=") for p in query.split("&")];
    result = {};
    for p in parts {
        if (len(p) == 2) {
            result[p[0]] = p[1];
        }
        if (len(p) == 1) {
            result[p[0]] = None;
        }
    }
    return result;
}

